CREATE OR REPLACE FUNCTION ECAMS.GETBASENAME
(ACPTNO IN VARCHAR2,SERNO IN VARCHAR2)
RETURN VARCHAR2
IS
   VBASENAME  VARCHAR2(200);
 --- 자신의 기준프로그램이 프로프레임형상항목인지 CHECK
BEGIN
    SELECT  C.CR_RSRCNAME
      INTO  VBASENAME
      FROM  CMR1010 C,CMR1010 A
     WHERE  A.CR_ACPTNO=ACPTNO
       AND  A.CR_SERNO=SERNO
       AND  A.CR_ACPTNO=C.CR_ACPTNO
       AND  A.CR_BASEITEM=C.CR_ITEMID;

     RETURN VBASENAME;
end;